/// What one status event records. issued: the assessment was issued; superseded: a newer assessment (successor) replaces it; invalidated: a listed change made it stale (results are never rewritten); withdrawn: the issuer no longer stands behind the claim. Key revocation (key log) and expiry (the claim's expires_ms) are not status changes.
#[derive(Debug, Clone, PartialEq)]
pub enum AssessmentStatusChange {
    Issued,
    Superseded { successor: Id, reason: String },
    Invalidated { triggers: Vec<AssessmentInvalidation>, reason: String },
    Withdrawn { reason: String },
}

impl AssessmentStatusChange {
    pub fn kind(&self) -> &'static str {
        match self {
            AssessmentStatusChange::Issued => "issued",
            AssessmentStatusChange::Superseded { .. } => "superseded",
            AssessmentStatusChange::Invalidated { .. } => "invalidated",
            AssessmentStatusChange::Withdrawn { .. } => "withdrawn",
        }
    }
}

impl Canon for AssessmentStatusChange {
    fn to_json(&self) -> Json {
        let mut m = BTreeMap::new();
        m.insert("kind".to_owned(), Json::Str(self.kind().to_owned()));
        match self {
            AssessmentStatusChange::Issued => {}
            AssessmentStatusChange::Superseded { successor, reason } => {
                put(&mut m, "successor", successor);
                put(&mut m, "reason", reason);
            }
            AssessmentStatusChange::Invalidated { triggers, reason } => {
                put(&mut m, "triggers", triggers);
                put(&mut m, "reason", reason);
            }
            AssessmentStatusChange::Withdrawn { reason } => {
                put(&mut m, "reason", reason);
            }
        }
        Json::Obj(m)
    }
    fn from_json(j: &Json, path: &str) -> Result<Self, DecodeError> {
        let m = obj(j, path)?;
        let kind: String = req(m, "kind", path)?;
        match kind.as_str() {
            "issued" => {
                only_fields(m, &["kind"], path)?;
                Ok(AssessmentStatusChange::Issued)
            }
            "superseded" => {
                only_fields(m, &["successor", "reason", "kind"], path)?;
                Ok(AssessmentStatusChange::Superseded { successor: req(m, "successor", path)?, reason: req(m, "reason", path)? })
            }
            "invalidated" => {
                only_fields(m, &["triggers", "reason", "kind"], path)?;
                Ok(AssessmentStatusChange::Invalidated { triggers: req(m, "triggers", path)?, reason: req(m, "reason", path)? })
            }
            "withdrawn" => {
                only_fields(m, &["reason", "kind"], path)?;
                Ok(AssessmentStatusChange::Withdrawn { reason: req(m, "reason", path)? })
            }
            other => Err(unknown_variant(path, "AssessmentStatusChange", other)),
        }
    }
}

